/**
 * Off-thread LZ compression for the periodic autosave.
 * pagehide and manual saves stay on the main thread: a worker cannot finish
 * during unload, and localStorage is main-thread only.
 */

interface CompressResponse {
    id: number;
    compressed?: string;
    error?: string;
}

type PendingCompress = {
    resolve: (compressed: string) => void;
    reject: (error: Error) => void;
};

let worker: Worker | null = null;
let workerBroken = false;
let nextId = 1;
const pending = new Map<number, PendingCompress>();

function failAll(error: Error): void {
    workerBroken = true;
    const current = worker;
    worker = null;
    if (current) current.terminate();
    for (const entry of pending.values()) entry.reject(error);
    pending.clear();
}

function getWorker(): Worker | null {
    if (workerBroken || typeof Worker === 'undefined') return null;
    if (worker) return worker;
    try {
        const created = new Worker(new URL('./saveCompress.worker.ts', import.meta.url), { type: 'module' });
        created.onmessage = (event: MessageEvent<CompressResponse>) => {
            const data = event.data;
            if (!data || typeof data.id !== 'number') return;
            const entry = pending.get(data.id);
            if (!entry) return;
            pending.delete(data.id);
            if (typeof data.compressed === 'string') entry.resolve(data.compressed);
            else entry.reject(new Error(data.error || 'save compress worker failed'));
        };
        created.onerror = () => {
            failAll(new Error('save compress worker failed'));
        };
        worker = created;
        return created;
    } catch {
        workerBroken = true;
        return null;
    }
}

export function compressUtf16InWorker(json: string): Promise<string> {
    const current = getWorker();
    if (!current) return Promise.reject(new Error('save compress worker unavailable'));
    const id = nextId;
    nextId += 1;
    return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
            if (!pending.has(id)) return;
            pending.delete(id);
            reject(new Error('save compress worker timed out'));
        }, 8000);
        pending.set(id, {
            resolve: (compressed) => {
                clearTimeout(timer);
                resolve(compressed);
            },
            reject: (error) => {
                clearTimeout(timer);
                reject(error);
            },
        });
        try {
            current.postMessage({ id, json });
        } catch (error) {
            clearTimeout(timer);
            pending.delete(id);
            reject(error instanceof Error ? error : new Error(String(error)));
        }
    });
}
